//   dsplit3  = PROTECT(allocMatrix(REALSXP, splitcount, 3));
//
// allocMatrix(REALSXP, nrow, ncol) produces a SEXPREC with:
//   s->type   = REALSXP (14)
//   s->length = nrow * ncol
//   s->nrow   = nrow
//   s->ncol   = ncol
//   s->data   = double[nrow * ncol], zero-initialized, column-major layout
//
// Column j starts at REAL(s) + j * nrow.  The rpart source advances dptr
// by nrow per column: for (i = 0; i < ncol; i++) { col[i] = dptr; dptr += nrow; }
